import re
from typing import List, Tuple, Any


def _split_logical_records(raw: str) -> List[str]:
    records = []
    start = 0
    quote = None
    i = 0
    field_start = True
    n = len(raw)

    while i < n:
        ch = raw[i]
        if quote is not None:
            if ch == quote:
                if i + 1 < n and raw[i + 1] == quote:
                    i += 2
                    continue
                quote = None
            i += 1
            continue

        if field_start and ch in ('"', "'"):
            quote = ch
            field_start = False
            i += 1
            continue

        if ch in ",;":
            field_start = True
        elif ch in "\r\n":
            records.append(raw[start:i])
            if ch == "\r" and i + 1 < n and raw[i + 1] == "\n":
                i += 1
            start = i + 1
            field_start = True
        else:
            field_start = False
        i += 1

    if start < n or raw.endswith(("\n", "\r")):
        records.append(raw[start:])
    return records


def _parse_record(text: str, delimiters: str = ",",
                  quote_chars: str = '"') -> List[str]:
    fields = []
    buf = []
    quote = None
    field_start = True
    i = 0

    while i < len(text):
        ch = text[i]

        if quote is not None:
            if ch == quote:
                if i + 1 < len(text) and text[i + 1] == quote:
                    buf.append(quote)
                    i += 2
                    continue
                quote = None
            else:
                buf.append(ch)
            i += 1
            continue

        if field_start and ch in quote_chars:
            quote = ch
            field_start = False
            i += 1
            continue

        if ch in delimiters:
            fields.append("".join(buf))
            buf = []
            field_start = True
            i += 1
            continue

        buf.append(ch)
        if ch not in " \t":
            field_start = False
        i += 1

    fields.append("".join(buf))
    return fields


def _looks_like_header(row: List[str]) -> bool:
    if len(row) < 2:
        return False
    first = row[0].strip().lower()
    second = row[1].strip().lower()
    return first in ("date", "day", "datetime", "timestamp") and second in (
        "time", "hour"
    ) or ("date" in first and "time" in second)


def _fit_width(row: List[str], width: int, header: List[str]) -> List[str]:
    if len(row) == width:
        return row[:]
    if len(row) < width:
        return row[:] + [""] * (width - len(row))

    url_index = None
    for i, value in enumerate(row):
        if re.match(r"(?i)^[a-z][a-z0-9+.-]*://", value.strip()):
            url_index = i
            break

    description_index = None
    for i, name in enumerate(header):
        name_l = name.lower()
        if "description" in name_l or name_l in ("details", "detail", "description"):
            description_index = i
            break

    if description_index is None:
        if url_index is not None and url_index > 0:
            description_index = min(url_index - 1, width - 2)
        else:
            description_index = max(0, width - 2)

    if url_index is not None and url_index > description_index:
        end = url_index
        merged = row[description_index:end]
        result = row[:description_index]
        result.append(",".join(merged))
        result.extend(row[end:])
    else:
        end = len(row) - (width - description_index - 1)
        end = max(description_index + 1, end)
        result = row[:description_index]
        result.append(",".join(row[description_index:end]))
        result.extend(row[end:])

    if len(result) > width:
        result = result[:width - 1] + [",".join(result[width - 1:])]
    if len(result) < width:
        result.extend([""] * (width - len(result)))
    return result


def parse_csv(raw_csv: str):
    expected_width = 9
    physical_records = _split_logical_records(raw_csv)
    parsed = []

    for record in physical_records:
        standard = _parse_record(record, ",", '"')
        if ";" in record and len(standard) != expected_width:
            mixed = _parse_record(record, ",;", "\"'")
            if len(mixed) >= 2:
                standard = mixed
        parsed.append((record, standard))

    header_index = None
    for i, (_, row) in enumerate(parsed):
        if _looks_like_header(row):
            header_index = i
            break

    if header_index is None:
        for i, (_, row) in enumerate(parsed):
            if len(row) >= expected_width and any(
                "date" in cell.lower() for cell in row[:3]
            ):
                header_index = i
                break

    if header_index is None:
        header_index = 0

    header = _fit_width(parsed[header_index][1], expected_width, [])
    rows = []

    for record, row in parsed[header_index + 1:]:
        if len(row) == 1 and row[0] == "" and record == "":
            continue
        if ";" in record and len(row) != expected_width:
            row = _parse_record(record, ",;", "\"'")
        rows.append(_fit_width(row, expected_width, header))

    return {"columns": header, "rows": rows}
